14	/// Avx512SimdExtension — AVX-512 512-bit Vector-Extension (Skylake-X+, Ice Lake Server,
15	/// AMD Zen 4+). NICHT auf allen x86_64-CPUs (Haswell hat keinen AVX-512).
16	/// Optional Pflicht-Check: compatible_with_x86() = true, aber Subset von CPUs.
17	class Avx512SimdExtension : public SimdExtensionStrategyBase<Avx512SimdExtension> {
18	public:
19	    using topic_tag = ::comdare::cache_engine::hardware::concepts::HardwareTopicTag;
20	    using axis_tag  = subaxes::vector_width_tag;
21	    using family_id = std::integral_constant<int, 3>;
22	
23	    static constexpr bool enabled = flags::avx512_enabled;
24	
25	    [[nodiscard]] static constexpr bool             is_active() noexcept { return true; }
26	    [[nodiscard]] static constexpr int              vector_width_bits() noexcept { return 512; }
27	    [[nodiscard]] static constexpr bool             compatible_with_x86() noexcept { return true; }
28	    [[nodiscard]] static constexpr bool             compatible_with_arm() noexcept { return false; }
29	    [[nodiscard]] static constexpr bool             compatible_with_riscv() noexcept { return false; }
30	    [[nodiscard]] static constexpr bool             compatible_with_powerpc() noexcept { return false; }
31	    [[nodiscard]] static constexpr std::string_view name() noexcept { return "simd_ext_avx512"; }
32	    [[nodiscard]] static constexpr std::string_view family_name() noexcept {
33	        return "Avx512SimdExtension (x86_64 Skylake-X+ 512-bit, Ice Lake Server/Zen 4+)";
34	    }
35	    [[nodiscard]] static constexpr std::string_view flag_suffix() noexcept { return "AVX512"; }
36	
37	    // ─── R7.7.b Vollstaendige SSE/AVX/AVX-512 Schichten (Server-Default) ────
38	    // Annahme: Skylake-X/Cascade Lake/Ice Lake Server/Zen 4 — Server-CPU mit
39	    // VNNI (DBMS-relevant), BW/DQ/VL/VPOPCNTDQ (Bitmap-Index-Beschleunigung).
40	    // Xeon Phi KNL-Sub-Flags (ER/PF) = false (irrelevant fuer DBMS).
41	    // BF16/FP16 = true ab Sapphire Rapids/Cooper Lake fuer ML-Workloads.
42	    [[nodiscard]] static constexpr bool provides_sse() noexcept { return true; }
43	    [[nodiscard]] static constexpr bool provides_sse2() noexcept { return true; }
44	    [[nodiscard]] static constexpr bool provides_sse3() noexcept { return true; }
45	    [[nodiscard]] static constexpr bool provides_ssse3() noexcept { return true; }
46	    [[nodiscard]] static constexpr bool provides_sse4_1() noexcept { return true; }
47	    [[nodiscard]] static constexpr bool provides_sse4_2() noexcept { return true; }
48	    [[nodiscard]] static constexpr bool provides_avx() noexcept { return true; }
49	    [[nodiscard]] static constexpr bool provides_avx2() noexcept { return true; }
50	    [[nodiscard]] static constexpr bool provides_avx512f() noexcept { return true; }  // Pflicht-Basis
51	    [[nodiscard]] static constexpr bool provides_avx512cd() noexcept { return true; } // Conflict Detection
52	    // ER+PF nur Xeon Phi KNL — default false (Defaults aus Base)
53	    [[nodiscard]] static constexpr bool provides_avx512bw() noexcept { return true; }
54	    [[nodiscard]] static constexpr bool provides_avx512dq() noexcept { return true; }
55	    [[nodiscard]] static constexpr bool provides_avx512vl() noexcept { return true; }
56	    [[nodiscard]] static constexpr bool provides_avx512ifma() noexcept { return true; }
57	    [[nodiscard]] static constexpr bool provides_avx512vbmi() noexcept { return true; }
58	    [[nodiscard]] static constexpr bool provides_avx512vbmi2() noexcept { return true; }
59	    [[nodiscard]] static constexpr bool provides_avx512vnni() noexcept { return true; } // DBMS Vector-Indexes
60	    [[nodiscard]] static constexpr bool provides_avx512bitalg() noexcept { return true; }
61	    [[nodiscard]] static constexpr bool provides_avx512vpopcntdq() noexcept { return true; } // Bitmap-Indexes
62	    [[nodiscard]] static constexpr bool provides_avx512bf16() noexcept {
63	        return true;
64	    } // Cooper Lake+ / Sapphire Rapids+
65	    [[nodiscard]] static constexpr bool provides_avx512fp16() noexcept { return true; } // Sapphire Rapids+
66	
67	    // ─── R7.7.c Topologie: 1 AVX-512 Unit/Sockel, P-Core-only (Hybrid) ──────
68	    // KRITISCH: Intel Alder Lake/Raptor Lake/Meteor Lake disabled AVX-512 in BIOS
69	    // wegen E-Cores die kein AVX-512 unterstuetzen. AMD Zen 4 hat AVX-512 in
70	    // allen Cores. Konservativer Default: false (sicher fuer Hybrid).
71	    [[nodiscard]] static constexpr int  units_per_socket() noexcept { return 1; }
72	    [[nodiscard]] static constexpr bool accessible_from_efficiency_cores() noexcept { return false; }
73	};
